      {
        "letra": "A",
        "texto": "pod e ser, uma vez que é comparável."
      },
      {
        "letra": "B",
        "texto": "pod e ser, uma vez que é tempestiva."
      },
      {
        "letra": "C",
        "texto": "não pod e ser, uma vez que não é neutra."
      },
      {
        "letra": "D",
        "texto": "não pod e ser, uma vez que não é verificável."
      }
